edits.after:
static u32 s32ton(__s32 value, unsigned int n)
{
	s32 a;

	if (!n)
		return 0;

	a = value >> (n - 1);

	if (a && a != -1)
		return value < 0 ? 1 << (n - 1) : (1 << (n - 1)) - 1;
	return value & ((1 << n) - 1);
}

